 private fun restoreDirectory(r:BridgeRequest):Any? {val name=relative(r.params.optString("name"));val uri=activity.getSharedPreferences("directories.${manifest.id}",android.content.Context.MODE_PRIVATE).getString(name,null)?.let{android.net.Uri.parse(it)}?:return null;val id="runtime-directory-${System.nanoTime()}";directories[id]=uri;return JSONObject().put("id",id).put("name",name)}
 private fun forgetDirectory(r:BridgeRequest){activity.getSharedPreferences("directories.${manifest.id}",android.content.Context.MODE_PRIVATE).edit().remove(relative(r.params.optString("name"))).apply()}
 private fun dialogAlert(r:BridgeRequest){android.app.AlertDialog.Builder(activity).setTitle(r.params.optString("title")).setMessage(r.params.optString("message")).setPositiveButton(r.params.optString("buttonText","OK")){_,_->send(BridgeResponse(r.id,true,JSONObject.NULL))}.setOnCancelListener{send(BridgeResponse(r.id,true,JSONObject.NULL))}.show()}
 private fun dialogConfirm(r:BridgeRequest){android.app.AlertDialog.Builder(activity).setTitle(r.params.optString("title")).setMessage(r.params.optString("message")).setPositiveButton(r.params.optString("confirmText","OK")){_,_->send(BridgeResponse(r.id,true,true))}.setNegativeButton(r.params.optString("cancelText","Cancel")){_,_->send(BridgeResponse(r.id,true,false))}.setOnCancelListener{send(BridgeResponse(r.id,true,false))}.show()}
 private fun dialogPrompt(r:BridgeRequest){val input=android.widget.EditText(activity).apply{setText(r.params.optString("defaultValue"));r.params.optInt("maxLength",0).takeIf{it>0}?.let{filters=arrayOf(android.text.InputFilter.LengthFilter(it))}};android.app.AlertDialog.Builder(activity).setTitle(r.params.optString("title")).setMessage(r.params.optString("message")).setView(input).setPositiveButton(r.params.optString("confirmText","OK")){_,_->send(BridgeResponse(r.id,true,input.text.toString()))}.setNegativeButton(r.params.optString("cancelText","Cancel")){_,_->send(BridgeResponse(r.id,true,JSONObject.NULL))}.setOnCancelListener{send(BridgeResponse(r.id,true,JSONObject.NULL))}.show()}
 private fun canOpen(p:JSONObject):Any { val url=p.optString("url");val uri=runCatching{android.net.Uri.parse(url)}.getOrNull();val ok=uri!=null&&uri.scheme in setOf("https","http","mailto","tel","geo")&&activity.packageManager.resolveActivity(android.content.Intent(android.content.Intent.ACTION_VIEW,uri),0)!=null;return JSONObject().put("supported",ok) }
 private fun openUrl(p:JSONObject){val uri=android.net.Uri.parse(p.optString("url"));if(uri.scheme !in setOf("https","http","mailto","tel","geo"))throw ApiException("system_url_not_allowed","URL scheme is not allowed");try{activity.startActivity(android.content.Intent(android.content.Intent.ACTION_VIEW,uri))}catch(_:Exception){throw ApiException("system_no_handler","No application can open URL")}}
 private fun openFile(r:BridgeRequest){val f=files[r.params.optString("fileId")]?:throw ApiException("file_not_found","File handle not found");try{activity.startActivity(android.content.Intent(android.content.Intent.ACTION_VIEW).setDataAndType(f.uri,f.mime?:"application/octet-stream").addFlags(android.content.Intent.FLAG_GRANT_READ_URI_PERMISSION))}catch(_:Exception){throw ApiException("system_no_handler","No application can open file")}}
 private fun key(r:BridgeRequest)=r.params.optString("key").ifBlank{r.params.optString("id").ifBlank{throw IllegalArgumentException("key is required")}}
 private fun isPublic(r:BridgeRequest)=r.params.optBoolean("public")||r.params.optString("scope")=="public"
  private fun dispatchPeer(raw:String){
   val r=try{BridgeRequest.parse(raw)}catch(_:Exception){return}
   if(!BuildConfig.DEBUG){send(BridgeResponse(r.id,false,errorCode="feature_unavailable",errorMessage="Peer transport is unavailable in release builds"));return}
   try{
    ensurePermission("local.peers",r)
    PeerManager.subscribe(manifest.id){name,payload->event(name,payload)}
    if(r.method!="peers.stopDiscovery")PeerManager.start(activity)
    val peerId=r.params.optString("peerId")
    val channel=r.params.optString("channel",r.params.optString("name"))
    if(r.method=="peers.connect"){
     Thread {
      try{PeerManager.connect(peerId);send(BridgeResponse(r.id,true,JSONObject().put("peerId",peerId).put("status","connected")))}
      catch(e:ApiException){send(BridgeResponse(r.id,false,errorCode=e.code,errorMessage=e.message))}
      catch(_:Exception){send(BridgeResponse(r.id,false,errorCode="peer_connection_failed",errorMessage="Could not connect to peer"))}
     }.start()
     return
    }
    val result=when(r.method){
     "peers.startDiscovery"->JSONObject.NULL
     "peers.stopDiscovery"->{PeerManager.unsubscribe(manifest.id);PeerManager.stop();JSONObject.NULL}
     "peers.list"->PeerManager.list()
     "peers.disconnect"->{PeerManager.disconnect(peerId);JSONObject.NULL}
     "peers.connections"->PeerManager.connections()
     "peers.openChannel"->PeerManager.openChannel(manifest.id,peerId,channel)
     "peers.closeChannel"->PeerManager.closeChannel(manifest.id,peerId,channel)
     "peers.sendMessage"->{if(!r.params.has("message")&&!r.params.has("data"))throw ApiException("invalid_params","message is required");PeerManager.sendMessage(manifest.id,peerId,channel,if(r.params.has("message"))r.params.opt("message") else r.params.opt("data"))}
     else->throw ApiException("peer_transport_unavailable","Peer transport operation is not available")
    }
    send(BridgeResponse(r.id,true,result))
   }catch(_:PendingPermission){}
   catch(e:ApiException){send(BridgeResponse(r.id,false,errorCode=e.code,errorMessage=e.message))}
   catch(e:IllegalArgumentException){send(BridgeResponse(r.id,false,errorCode="invalid_params",errorMessage=e.message?:"Invalid parameters"))}
   catch(_:Exception){send(BridgeResponse(r.id,false,errorCode="internal_error",errorMessage="Peer operation failed"))}
  }
 fun clearFiles(){localDevices.close();stopNetworkMonitoring();PeerManager.unsubscribe(manifest.id);files.clear();directories.clear();appDirectories.clear();readOnlyFiles.clear()}; fun clearTimers(){timers.values.forEach{handler.removeCallbacks(it.task)};timers.clear()}
}
private class RuntimeTimer(val id:String){lateinit var task:Runnable}
class ApiException(val code:String,override val message:String):Exception(message)
private class PendingPermission:Exception()
